USE store_db;
CREATE TABLE IF NOT EXISTS bills (id INT AUTO_INCREMENT PRIMARY KEY, total DECIMAL(12, 2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bill_items (id INT AUTO_INCREMENT PRIMARY KEY, bill_id INT NOT NULL, item_id INT NOT NULL, item_name VARCHAR(150) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10, 2) NOT NULL, FOREIGN KEY (bill_id) REFERENCES bills(id), FOREIGN KEY (item_id) REFERENCES items(id), CHECK (quantity > 0));
